import{z as o,x as i,o as r,c as d,q as B,j as n,D as t,d as a,s as A,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"多实验的资源调度","description":"","frontmatter":{"title":"多实验的资源调度","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-multiexp-scheduling.md","filePath":"llm/ti-multiexp-scheduling.md","lastUpdated":1791413859000}'),g={name:"llm/ti-multiexp-scheduling.md"};function p(D,E,m,u,h,C){const l=i("Mermaid");return r(),d("div",null,[E[2]||(E[2]=B('<h1 id="多实验的资源调度" tabindex="-1">多实验的资源调度 <a class="header-anchor" href="#多实验的资源调度" aria-label="Permalink to &quot;多实验的资源调度&quot;">​</a></h1><div class="epigraph"><p>机群调度的两难是：长跑要稳定，短测要即时；把两类负载放进同一条先来先服务的队列，两类都得不到满足。</p><footer>—— 据 Slurm/Kubernetes 调度实践与机群公平调度经验整理</footer></div><p><a href="/llm/ti-experiment-tracking">上一课</a>把团队记忆外置成数据库；团队共享的不止记忆，还有<strong>机群</strong>。同一时刻，预训练长跑、消融短测、调试作业挤在同一批卡上，先到先得很快退化成嗓门大者得。单作业视角到此为止，本课进入管理单元：多实验的资源调度。机群公平性的机制在<a href="/llm/cluster-fair-scheduling">机群公平调度</a>已写，异构卡型的搭配在<a href="/llm/hetero-cluster">异构集群调度</a>；本课写<strong>实验负载</strong>特有的一面：负载分型、gang 分配、抢占与回填。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实验负载与稳定服务负载的差别在<strong>弹性与原子性</strong>。原子性：一个 32 卡的分布式作业分到 30 卡也开不了工——所有 rank 要同时到位、同时起步；没有整块分配的保证，碎片卡位只能空转等凑齐，机群利用率远低于单卡利用率之和。弹性不均：消融短测只跑几十分钟、要的是<strong>现在</strong>，长跑以周计、要的是<strong>不被打断</strong>；排队半小时对长跑无所谓，对想看结论的研究者意味着这一天白过。抢占的风险不对称：杀刚起步的调试作业无所谓，杀跑了六天的长跑是事故，除非它的检查点真能无缝续训。</p><p><span class="marginnote">术语翻译：gang 调度就是「全有或全无」的分配方式——分布式作业的每个副本（rank）必须同时拿到卡、同时启动，缺一个都开不了工。像拔河队八个人必须到齐才能上场比赛，来了七个也只能干等。数字实例：32 卡的作业落在散成 30+2 碎片的机群上，哪怕利用率九成，它依然一步都跑不了。</span></p><h3 id="负载分型与池化" tabindex="-1">负载分型与池化 <a class="header-anchor" href="#负载分型与池化" aria-label="Permalink to &quot;负载分型与池化&quot;">​</a></h3><p>第一刀是按 SLA 分三型：<strong>长跑型</strong>（预训练主力的独占整块、最高优先级保护）、<strong>批处理型</strong>（消融与超参扫描的批量吞吐、可排队可抢占）、<strong>交互型</strong>（调试与 notebook 的小卡短窗、配额限流保即时）。分型之后池化：批处理型共享可抢占池，交互型限定小卡与时长上限。池子之间留溢流——交互池空闲时批处理可借用，被高优先级作业赎回时靠检查点退出。</p><p><span class="marginnote">回填（backfill）保住的是短作业的产能：长跑排队等整块资源时，允许预估不会推迟队头长跑的小作业插空进卡。没有回填的机群常见奇景是「利用率八成，谁都在等」——碎片被短作业填上，队头的整块需求不被推迟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>调度策略按四条落地。其一，<strong>gang 调度</strong>是分布式作业的硬要求：全有或全无分配，凑不齐就排队，不用部分资源开工。其二，<strong>优先级与抢占</strong>：抢占只对开了<a href="/llm/ti-checkpoint-engineering">高频检查点</a>的作业放行，被抢时存盘退出、资源释放，恢复时排队重入——检查点频率从此有了第二个决定因素（第一个是故障率）。其三，<strong>公平份额</strong>：跨团队按份额分池，空转份额可借出、可赎回，记账进<a href="/llm/ti-cost-analysis">成本分析</a>的口径；份额争论以跟踪库的用量记录为唯一依据。其四，<strong>配额护栏</strong>：交互型限单作业时长与卡数，批处理型限并发数，防止单一实验吞掉整池。</p>',11)),(r(),n(s,null,{default:t(()=>[A(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22%E4%BD%9C%E4%B8%9A%E6%8F%90%E4%BA%A4%3A%20%E5%A3%B0%E6%98%8E%E7%B1%BB%E5%9E%8B%E4%B8%8E%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%20--%3E%20T%7B%22%E8%B4%9F%E8%BD%BD%E5%88%86%E5%9E%8B%22%7D%0A%20%20T%20--%3E%7C%E9%95%BF%E8%B7%91%E5%9E%8B%7C%20DED%5B%22%E7%8B%AC%E5%8D%A0%E6%95%B4%E5%9D%97%2C%20%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20T%20--%3E%7C%E6%89%B9%E5%A4%84%E7%90%86%E5%9E%8B%7C%20POOL%5B%22%E5%8F%AF%E6%8A%A2%E5%8D%A0%E6%B1%A0%2C%20%E6%8E%92%E9%98%9F%E4%B8%8E%E5%9B%9E%E5%A1%AB%22%5D%0A%20%20T%20--%3E%7C%E4%BA%A4%E4%BA%92%E5%9E%8B%7C%20INT%5B%22%E5%B0%8F%E5%8D%A1%E7%9F%AD%E7%AA%97%2C%20%E9%85%8D%E9%A2%9D%E9%99%90%E6%B5%81%22%5D%0A%20%20POOL%20--%3E%7C%E8%A2%AB%E8%B5%8E%E5%9B%9E%7C%20CKP%5B%22%E5%AD%98%E6%A3%80%E6%9F%A5%E7%82%B9%E9%80%80%E5%87%BA%2C%20%E6%8E%92%E9%98%9F%E9%87%8D%E5%85%A5%22%5D%0A%20%20DED%20--%3E%20RUN%5B%22%E5%BC%80%E5%B7%A5%22%5D%0A%20%20POOL%20--%3E%20RUN%0A%20%20INT%20--%3E%20RUN%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("分型有效的机理是"),e("strong",null,"把矛盾拆开"),a("：长跑与短测的冲突本质是 SLA 不同，一条队列一个策略无法同时满足两类延迟目标；分池后每类负载有匹配自己的排队论参数。抢占与检查点挂钩的机理是安全性：抢占把「资源被夺」从致命错误降级为例行事件的前提，是状态可以在任意时刻落盘——基础设施各课在这里咬合成环。回填的机理是保守调度：以「不推迟队头」为约束放行插空，牺牲一点等待顺序的公平，换整块碎片时间的产出。")],-1)),E[5]||(E[5]=e("p",null,[a("公平份额要防的病是"),e("strong",null,"囤积"),a("：团队为旺季预留却平时空转，借出与赎回机制让空转份额流动起来；机制只在记账可信时工作，这正是上一课与「成本分析」课的存在理由。")],-1)),(r(),n(s,null,{default:t(()=>[A(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%89%B9%E5%A4%84%E7%90%86%E4%BD%9C%E4%B8%9A%E8%BF%90%E8%A1%8C%E4%B8%AD%22%5D%20--%3E%20P%7B%22%E6%94%B6%E5%88%B0%E8%B5%8E%E5%9B%9E%E4%BF%A1%E5%8F%B7%22%7D%0A%20%20P%20--%3E%7C%22%E5%B7%B2%E5%BC%80%E9%AB%98%E9%A2%91%E6%A3%80%E6%9F%A5%E7%82%B9%22%7C%20C%5B%22%E5%AD%98%E7%9B%98%E9%80%80%E5%87%BA%2C%20%E9%87%8A%E6%94%BE%E8%B5%84%E6%BA%90%22%5D%0A%20%20P%20--%3E%7C%22%E6%9C%AA%E5%BC%80%E6%A3%80%E6%9F%A5%E7%82%B9%22%7C%20W%5B%22%E4%B8%8D%E5%85%81%E8%AE%B8%E8%A2%AB%E6%8A%A2%3A%20%E7%BB%A7%E7%BB%AD%E8%BF%90%E8%A1%8C%22%5D%0A%20%20C%20--%3E%20Q%5B%22%E6%8E%92%E9%98%9F%E7%AD%89%E5%BE%85%E9%87%8D%E6%96%B0%E5%87%91%E9%BD%90%E8%B5%84%E6%BA%90%22%5D%0A%20%20Q%20--%3E%20RE%5B%22%E9%87%8D%E5%85%A5%3A%20%E4%BB%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E6%81%A2%E5%A4%8D%22%5D%0A%20%20RE%20--%3E%20N%7B%22%E8%A2%AB%E6%8A%A2%E5%87%A0%E6%AC%A1%E4%BA%86%3F%22%7D%0A%20%20N%20--%3E%7C%22%E4%BD%8E%E4%BA%8E%E4%B8%8A%E9%99%90%22%7C%20R%0A%20%20N%20--%3E%7C%22%E8%BE%BE%E5%88%B0%E4%B8%8A%E9%99%90%22%7C%20UP%5B%22%E5%8D%87%E4%BC%98%E5%85%88%E7%BA%A7%E6%88%96%E6%94%B9%E5%88%A4%E9%95%BF%E8%B7%91%E5%9E%8B%E9%87%8D%E6%8E%92%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">直觉类比：公平份额像小区车位——每户有固定车位（份额），不住的时候可以借给访客（借出），回来时有权请访客挪车（赎回）。没有这套规则，车位要么被一家常年霸占，要么人人乱停；借出与赎回让资源流动起来，记账则是判谁该挪车的依据。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管机群内的实验编排，不管单卡内的多任务共享（MPS、时间片属系统层），也不管跨机群与跨云的调度——那是异构集群课的口径。抢占上限要设：被抢三次还没跑完的批处理作业应升优先级或降级为长跑型重排，无限抢占会让某些作业永远跑不完。调度器不知道实验的<strong>价值</strong>，它只执行声明的优先级；声明错了，机群在高效地跑错的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>负载分三型：长跑独占、批处理可抢占、交互限流，各配各的队列参数。</li><li>分布式作业 gang 分配全有或全无；碎片靠回填，约束是不推迟队头。</li><li>抢占只放行高频检查点的作业，恢复走排队重入。</li><li>公平份额可借可赎，记账进成本口径；调度器执行优先级，不判断价值。</li><li>出处：据 Slurm/Kubernetes 与内部机群调度实践整理；公平机制见<a href="/llm/cluster-fair-scheduling">机群公平调度</a>。</li></ul>',5))])}const _=o(g,[["render",p]]);export{f as __pageData,_ as default};
